{
  "hechos": [
    {
      "id": "H1",
      "texto": "El puente La Concordia fue cerrado al tránsito de vehículos y peatones.",
      "paginas": ["P1", "P2", "P3", "P4", "P5", "P6"]
    },
    {
      "id": "H2",
      "texto": "Se escuchaban crujidos en el puente desde hace semanas.",
      "paginas": ["P1", "P4", "P6"]
    },
    {
      "id": "H3",
      "texto": "Los ingenieros detectaron fisuras en dos vigas principales.",
      "paginas": ["P1", "P2", "P3", "P4", "P5", "P6"]
    },
    {
      "id": "H4",
      "texto": "El cierre afecta un corredor que transitan alrededor de 9.000 vehículos diarios.",
      "paginas": ["P1", "P2", "P3", "P4"]
    },
    {
      "id": "H5",
      "texto": "El desvío por la vía El Cedral suma unos 40 minutos al recorrido.",
      "paginas": ["P1", "P2", "P3", "P4", "P6"]
    },
    {
      "id": "H6",
      "texto": "Las autoridades prohibieron el paso de carros y peatones por el puente La Concordia.",
      "paginas": ["P3", "P4"]
    },
    {
      "id": "H7",
      "texto": "Marta Avendaño, habitante del barrio Los Almendros, contó que los estudiantes tienen que madrugar una hora más.",
      "paginas": ["P3"]
    },
    {
      "id": "H8",
      "texto": "En el barrio Las Acacias, la junta de acción comunal contó 60 familias que dependen del puente para ir a trabajar.",
      "paginas": ["P3"]
    },
    {
      "id": "H9",
      "texto": "Jorge Ospina, integrante de la junta comunal del barrio El Bosque, contó que se escuchaban crujidos en el puente desde hace semanas.",
      "paginas": ["P4"]
    },
    {
      "id": "H10",
      "texto": "En el barrio San José, la junta de acción comunal contó 473 familias que dependen del puente para ir a trabajar.",
      "paginas": ["P4"]
    },
    {
      "id": "H11",
      "texto": "Andrés Toro, docente del barrio Santa Rita, contó que hubo un trancón de más de dos horas en la vía El Cedral.",
      "paginas": ["P5", "P6"]
    },
    {
      "id": "H12",
      "texto": "En el barrio La Pradera, la junta de acción comunal contó 147 familias que dependen del puente para ir a trabajar.",
      "paginas": ["P6"]
    }
  ]
}
